import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;

public class CF_630_D2_E_Variant5 {
    public static void main(String[] args) throws Exception {
        InputStream is = System.in;
        BufferedReader br = new BufferedReader(new InputStreamReader(is));
        String[] tokens = br.readLine().split(" ");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        int L = Integer.parseInt(tokens[2]);
        int R = Integer.parseInt(tokens[3]);

        long mod = 998244353;
        long inv2 = powerMod(2, mod - 2, mod);
        long diff = R - L + 1;
        long p1 = diff / 2;
        long p2 = diff - p1;
        long answer;

        if ((n * m) % 2 == 1) {
            answer = powerMod(diff, n * m, mod);
        } else {
            long totalP1 = diff;
            long totalP2 = Math.abs(p1 - p2);
            long opt1 = powerMod(totalP1, n * m, mod);
            long opt2 = powerMod(totalP2, n * m, mod);
            long totalOpt = (opt1 + opt2) % mod;
            answer = (totalOpt * inv2) % mod;
        }
        System.out.println(answer);
    }

    static long powerMod(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
